  'land.nav.join': 'Participe', 'land.join.kicker': 'Junte-se a nós', 'land.join.title': 'Quer fazer parte do projeto?', 'land.join.text': 'O CM Reborn é um projeto de fã e sempre há espaço para mais gente. Escreva algumas linhas sobre você e no que gostaria de ajudar – e eu entro em contato.', 'land.join.b1': 'Desenvolvedores, designers e gente de dados de futebol', 'land.join.b2': 'Testadores que querem experimentar novidades antes de todo mundo', 'land.join.b3': 'Tradutores e pessoas que querem ajudar a comunidade', 'land.join.name': 'Nome', 'land.join.email': 'E-mail', 'land.join.role': 'No que você gostaria de ajudar?', 'land.join.message': 'Conte um pouco sobre você', 'land.join.placeholder': 'Quem é você e o que gostaria de fazer?', 'land.join.role.developer': 'Desenvolvimento', 'land.join.role.designer': 'Design e gráficos', 'land.join.role.data': 'Dados e bancos de dados', 'land.join.role.testing': 'Testes e relatos de bugs', 'land.join.role.translation': 'Tradução', 'land.join.role.community': 'Comunidade e conteúdo', 'land.join.role.other': 'Outro', 'land.join.send': 'Enviar', 'land.join.sending': 'Enviando…', 'land.join.thanks': 'Obrigado pelo contato!', 'land.join.thanksText': 'Sua mensagem foi recebida e eu vou responder por e-mail.', 'land.join.privacy': 'Seu nome e e-mail são usados só para responder a você.', 'land.join.offline': 'O formulário só funciona na versão principal do jogo.', 'land.join.goLive': 'Ir para o formulário', 'land.join.err.email': 'Confira seu endereço de e-mail.', 'land.join.err.limit': 'Mensagens demais – tente novamente mais tarde.', 'land.join.err.missing': 'Preencha seu nome e uma mensagem de pelo menos 10 caracteres.', 'land.join.err.other': 'Algo deu errado – tente novamente.',
